// Sammel-Decks: alle Vokabeln einer Unit auf einmal (Dopplungen entfernt).
// Neue Unit mit mehreren Abschnitten: hier eine Zeile [Name, Fach, Unit] ergaenzen.
// gesamt: true = die App zeigt es als erstes Deck seiner Unit.
(function () {
  const D = window.VT_DECKS;
  const sammel = {};
  for (const [name, fach, unit] of [
    ["Englisch — K3 gesamt: A World of Change – Globalization", "Englisch", "K3"],
    ["Englisch — K6 gesamt: The World of Work", "Englisch", "K6"],
  ]) {
    const keys = Object.keys(D).filter(k => D[k].fach === fach && D[k].unit === unit);
    const words = keys
      .flatMap(k => D[k].words)
      .filter((w, i, all) => all.findIndex(v => v.de === w.de && v.fs === w.fs) === i);
    const added = keys.map(k => D[k].added).sort().pop();
    sammel[name] = { fach, unit, added, gesamt: true, words };
  }
  window.VT_DECKS = Object.assign(sammel, D);
})();
